package com.cpf.education.online.transactionrequired.service;
import com.cpf.data.persistence.api.CpfCrudRepository; import com.cpf.data.persistence.api.annotation.CpfTransactional; import com.cpf.education.online.transactionrequired.dto.MemberRegistrationCommand; import com.cpf.education.online.transactionrequired.repository.MemberRegistrationRecord; import com.cpf.foundation.annotation.CpfService; import org.springframework.beans.factory.ObjectProvider; import org.springframework.transaction.annotation.Propagation;
@CpfService
/** MemberProfileRegistrationService는 여러 Service가 하나의 REQUIRED Local Transaction에 참여하는 Transaction Golden Path입니다. */
public class MemberProfileRegistrationService { private final ObjectProvider<CpfCrudRepository<MemberRegistrationRecord,String>> repositories; public MemberProfileRegistrationService(ObjectProvider<CpfCrudRepository<MemberRegistrationRecord,String>> repositories){this.repositories=repositories;}
 @CpfTransactional(propagation=Propagation.REQUIRED) public void saveProfile(MemberRegistrationCommand c){repository().save(new MemberRegistrationRecord(c.profileId(),"PROFILE","saved"));if(c.failProfile())throw new IllegalStateException("profile failure triggers REQUIRED rollback");}
 private CpfCrudRepository<MemberRegistrationRecord,String> repository(){var r=repositories.getIfAvailable();if(r==null)throw new IllegalStateException("CPF transaction repository is not configured");return r;} }
